import React from "react";
import styled from "styled-components";
import { useTranslation } from "react-i18next";

const Container = styled.div`
  display: flex;
  justify-content: center;
`;

const Wrapper = styled.div`
  margin-top: 20px;
  width: 90%;
  flex-direction: column;
`;

// Tiêu đề chính
const Title = styled.h1`
  font-size: 2rem;
  color: #1e3a8a;
  margin: 30px 0 10px;
  border-left: 5px solid #3498db;
  padding-left: 15px;
`;

// Nội dung đoạn văn
const Text = styled.p`
  font-size: 1.1rem;
  color: #333;
  line-height: 1.6;
  margin-bottom: 20px;
  text-align: justify;
`;

const Image = styled.img`
  width: 50%;
  height: auto;
  display: block;
  margin: 20px auto;
`;

const Home = () => {
  const { t } = useTranslation();

  return (
    <Container>
      <Wrapper>
        <Title>{t("homePage.title1")}</Title>
        <Text>{t("homePage.content1")}</Text>

        <Image src="/Acinetobacter-baumannii.jpg" alt="Bacteria" />

        <Text>{t("homePage.content2")}</Text>

        <Title>{t("home.title2")}</Title>
        <Image src="/nguyco.jpg" alt="Risk" />
        <Text>{t("home.content3")}</Text>

        <Title>{t("home.title3")}</Title>
        <Text>{t("home.content4")}</Text>

        <Title>{t("home.title4")}</Title>
        <Image src="/dauhieunhiemtrung.jpg" alt="Symptoms" />
        <Text>{t("home.content5")}</Text>

        <Title>{t("home.title5")}</Title>
        <Text>{t("home.content6")}</Text>
      </Wrapper>
    </Container>
  );
};


export default Home;
